class _UniffiFfiConverterBoolean:
    @classmethod
    def check_lower(cls, value):
        return not not value

    @classmethod
    def lower(cls, value):
        return 1 if value else 0

    @staticmethod
    def lift(value):
        return value != 0

    @classmethod
    def read(cls, buf):
        return cls.lift(buf.read_u8())

    @classmethod
    def write(cls, value, buf):
        buf.write_u8(value)


class RunHandleProtocol(typing.Protocol):
    """
    Controls one run.
"""
    
    def abort(self, reason: str) -> None:
        """
        Cancel the run immediately. It ends with status `aborted`.
"""
        raise NotImplementedError
    def is_finished(self, ) -> bool:
        raise NotImplementedError
    def pause(self, reason: str) -> None:
        """
        Stop scheduling new nodes; the run ends with status `paused` and a snapshot.
"""
        raise NotImplementedError
    def update_variable(self, selector: str,value_json: str) -> None:
        """
        Write a variable (`"conversation.topic"`) while the run is in progress.
"""
        raise NotImplementedError
    def wait_json(self, timeout_ms: int) -> typing.Optional[str]:
        """
        Block until the run finishes (or `timeout_ms` elapses) and return the result
        JSON (`{"status": "succeeded"|"failed"|"aborted"|"paused", "answer": ..., ...}`).
        Returns `None` on timeout. Do not call from a UI thread.
"""
        raise NotImplementedError

class RunHandle(RunHandleProtocol):
    """
    Controls one run.
"""
    
    _handle: ctypes.c_uint64
    
    def __init__(self, *args, **kwargs):
        raise ValueError("This class has no default constructor")

    def __del__(self):
        # In case of partial initialization of instances.
        handle = getattr(self, "_handle", None)
        if handle is not None:
            _uniffi_rust_call(_UniffiLib.uniffi_graphrt_ffi_fn_free_runhandle, handle)

    def _uniffi_clone_handle(self):
        return _uniffi_rust_call(_UniffiLib.uniffi_graphrt_ffi_fn_clone_runhandle, self._handle)

    # Used by alternative constructors or any methods which return this type.
    @classmethod
    def _uniffi_make_instance(cls, handle):
        # Lightly yucky way to bypass the usual __init__ logic
        # and just create a new instance with the required handle.
        inst = cls.__new__(cls)
        inst._handle = handle
        return inst
    def abort(self, reason: str) -> None:
        """
        Cancel the run immediately. It ends with status `aborted`.
"""
        
        _UniffiFfiConverterString.check_lower(reason)
        _uniffi_lowered_args = (
            self._uniffi_clone_handle(),
            _UniffiFfiConverterString.lower(reason),
        )
        _uniffi_lift_return = lambda val: None
        _uniffi_error_converter = None
        _uniffi_ffi_result = _uniffi_rust_call_with_error(
            _uniffi_error_converter,
            _UniffiLib.uniffi_graphrt_ffi_fn_method_runhandle_abort,
            *_uniffi_lowered_args,
        )
        return _uniffi_lift_return(_uniffi_ffi_result)
    def is_finished(self, ) -> bool:
        _uniffi_lowered_args = (
            self._uniffi_clone_handle(),
        )
        _uniffi_lift_return = _UniffiFfiConverterBoolean.lift
        _uniffi_error_converter = None
